CREATE TABLE IF NOT EXISTS mag_workforce(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,display_name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'operator',skills_json TEXT NOT NULL DEFAULT '[]',availability_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'active',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mag_client_intakes(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,business_name TEXT NOT NULL,industry TEXT NOT NULL DEFAULT '',goals_json TEXT NOT NULL DEFAULT '[]',pain_json TEXT NOT NULL DEFAULT '[]',channels_json TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'discovery',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mag_sops(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,name TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'operations',steps_json TEXT NOT NULL DEFAULT '[]',version INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mag_service_assignments(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,intake_id TEXT,workforce_id TEXT,service_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'planned',outcomes_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mag_training_paths(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL DEFAULT '',modules_json TEXT NOT NULL DEFAULT '[]',active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mag_referrals(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,referrer_id TEXT NOT NULL DEFAULT '',customer_ref TEXT NOT NULL DEFAULT '',event_type TEXT NOT NULL DEFAULT 'referral',amount REAL NOT NULL DEFAULT 0,currency TEXT NOT NULL DEFAULT 'USD',status TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_mag_workforce_tenant ON mag_workforce(tenant_id,status);
CREATE INDEX IF NOT EXISTS idx_mag_clients_tenant ON mag_client_intakes(tenant_id,status);